mapper.select:
select * from (
    select sm.*, m.machine_code, m.machine_name
    from T_NC_SPECIFY_MACHINE sm
    left join T_NC_MACHINE_INFO m on sm.machine_id = m.id
    where sm.DEL_FLAG = 0
    and m.DEL_FLAG = 0

        and INSTR(LINING_CODE, #{liningCode}) > 0


        and MACHINE_ID = #{machineId}


        and LINE_TYPE = #{lineType}


        and JOB_TYPE = #{jobType}


        ORDER BY sm.CREATE_TIME DESC

) t

    order by ${orderStr}
